// More sounds for the 2600 library. Same Preset shape as the ones in ../b2600.js (see CONTRACT.md → Preset).
// Slider positions from frequencies: `f(hz)` puts a VCO at hz on middle C, `lf(hz)` a VCO in LF mode at hz,
// `cut(hz)` the filter cutoff at hz. The same scales as the panel (see ../b2600.js).
const f = (hz) => Math.round((0.74 + 2.7 * (Math.log10(hz) - 1)) * 100) / 100;
const lf = (hz) => f(hz * 333.3);
const cut = (hz) => Math.round((0.87 + 2.7 * (Math.log10(hz) - 1)) * 100) / 100;

